UPDATE "recipes" SET "procedure_steps" = ARRAY['Zahřát čistou filtrovanou vodu (1,5 l na beginu) na 80–85 °C.', 'Přidat heřmánek pravý.', 'Louhovat 12 minut (nevařit).', 'Nechat 5 minut zakryté odstát.', 'Výluh přecedit.', 'Přidat třtinový cukr a míchat, dokud se úplně nerozpustí.', 'Přidat citronovou šťávu.', 'Přidat antioxidant: kyselina L-askorbová (vitamin C).', 'Doplnit čistou filtrovanou vodou do objemu (3 l na beginu).', 'Sirup zahřát na 75–80 °C.', 'Horký naplnit do připravených bag-in-boxů.']::text[], "procedure_checks" = ARRAY['voda nesmí vařit', 'výluh musí mít světle zlatou barvu', 'vůně musí být výrazně heřmánková', 'cukr musí být zcela rozpuštěný', 'finální objem 3 l na beginu']::text[] WHERE "slug" = 'hermankovy-sirup' AND "procedure_steps" IS NULL;
